parameters.text:
=Name: {{ $json.Name }}
Email: {{ $json.Email }}
Company: {{ $json.Company }}
Cards wanted (form dropdown): {{ $json['How many cards?'] }}
Message:
{{ $json.Message }}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "category": {
      "type": "string",
      "enum": [
        "team_order",
        "single_order",
        "design_request",
        "support",
        "partnership",
        "spam"
      ]
    },
    "priority": {
      "type": "string",
      "enum": [
        "hot",
        "warm",
        "cold"
      ]
    },
    "language": {
      "type": "string",
      "description": "ISO 639-1 code of the language the message text is written in, e.g. bg, en, de"
    },
    "estimated_cards": {
      "type": "number",
      "description": "Best estimate of how many cards they want, 0 if unknown"
    },
    "summary": {
      "type": "string",
      "description": "One sentence in English: who they are and what they want"
    },
    "reply_subject": {
      "type": "string",
      "description": "Email subject for the reply, in the lead's language"
    },
    "reply_draft": {
      "type": "string",
      "description": "The reply email body, following the rules"
    }
  },
  "required": [
    "category",
    "priority",
    "language",
    "estimated_cards",
    "summary",
    "reply_subject",
    "reply_draft"
  ]
}
